#!/usr/bin/env python3
import sys

import booster_robotics_sdk_python as b1


def print_help():
    print(
        """
Available commands (Lion Dance):
  help                    Show this help
  prep <on|off>           Call B1LocoClient.LionDancePrepare()
  start <1|2>             Call B1LocoClient.LionDanceStart()
  move <on|off>           Call B1LocoClient.LionDanceMove()
  raw_prep <on|off>       Send LionDancePrepareParameter via SendApiRequest()
  raw_start <1|2>         Send LionDanceStartParameter via SendApiRequest()
  raw_move <on|off>       Send LionDanceMoveParameter via SendApiRequest()
  status                  Print current mode/body control/actions
  quit / exit             Exit
"""
    )


def parse_on_off(value: str) -> bool:
    value = value.lower()
    if value == "on":
        return True
    if value == "off":
        return False
    raise ValueError("value must be on or off")


def parse_dance_idx(value: str) -> int:
    if value not in ("1", "2"):
        raise ValueError("dance index must be 1 or 2")
    return int(value)


def main():
    if len(sys.argv) < 2:
        print(f"Usage: {sys.argv[0]} networkInterface [robotName]")
        print(f"Example: {sys.argv[0]} eno1")
        sys.exit(-1)

    net_if = sys.argv[1]
    robot_name = sys.argv[2] if len(sys.argv) > 2 else None

    b1.ChannelFactory.Instance().Init(0, net_if)

    client = b1.B1LocoClient()
    if robot_name:
        client.InitWithName(robot_name)
    else:
        client.Init()

    print("Lion Dance CLI started.")
    print_help()

    while True:
        try:
            raw = input("> ").strip()
        except (EOFError, KeyboardInterrupt):
            print("\nExit.")
            break

        if not raw:
            continue

        parts = raw.split()
        cmd = parts[0]
        args = parts[1:]

        try:
            if cmd in ("help", "?"):
                print_help()

            elif cmd in ("quit", "exit"):
                print("Bye.")
                break

            elif cmd == "prep":
                if len(args) != 1:
                    print("Usage: prep <on|off>")
                    continue
                client.LionDancePrepare(parse_on_off(args[0]))
                print("[OK] LionDancePrepare sent.")

            elif cmd == "start":
                if len(args) != 1:
                    print("Usage: start <1|2>")
                    continue
                client.LionDanceStart(parse_dance_idx(args[0]))
                print("[OK] LionDanceStart sent.")

            elif cmd == "move":
                if len(args) != 1:
                    print("Usage: move <on|off>")
                    continue
                client.LionDanceMove(parse_on_off(args[0]))
                print("[OK] LionDanceMove sent.")

            elif cmd == "raw_prep":
                if len(args) != 1:
                    print("Usage: raw_prep <on|off>")
                    continue
                param = b1.LionDancePrepareParameter(parse_on_off(args[0]))
                ret = client.SendApiRequest(
                    b1.LocoApiId.kLionDancePrepare,
                    param.to_json_str(),
                )
                print(f"[OK] raw LionDancePrepare sent, ret={ret}.")

            elif cmd == "raw_start":
                if len(args) != 1:
                    print("Usage: raw_start <1|2>")
                    continue
                param = b1.LionDanceStartParameter(parse_dance_idx(args[0]))
                ret = client.SendApiRequest(
                    b1.LocoApiId.kLionDanceStart,
                    param.to_json_str(),
                )
                print(f"[OK] raw LionDanceStart sent, ret={ret}.")

            elif cmd == "raw_move":
                if len(args) != 1:
                    print("Usage: raw_move <on|off>")
                    continue
                param = b1.LionDanceMoveParameter(parse_on_off(args[0]))
                ret = client.SendApiRequest(
                    b1.LocoApiId.kLionDanceMove,
                    param.to_json_str(),
                )
                print(f"[OK] raw LionDanceMove sent, ret={ret}.")

            elif cmd == "status":
                status = client.GetStatus()
                print(f"current_mode         : {status.current_mode}")
                print(
                    f"current_body_control : "
                    f"{status.current_body_control}"
                )
                print(f"current_actions      : {status.current_actions}")

            else:
                print(f"Unknown command: {raw}")
                print("Type 'help' to show available commands.")

        except Exception as exc:
            print(f"[ERROR] Request failed: {exc}")


if __name__ == "__main__":
    main()
